-- Semilla territorial de la República Dominicana (RF-LO).
-- Fuente: división territorial ONE/JCE (raydelto/provincias_dominicanas) + regiones de planificación (Decreto 710-04/247-12).
-- Idempotente: cada fila se inserta solo si su Codigo no existe. Orden: Pais -> Region -> Provincia -> Municipio -> Distrito.
SET NOCOUNT ON;

IF NOT EXISTS (SELECT 1 FROM [Organization].[Paises] WHERE [Codigo]=N'DO')
INSERT INTO [Organization].[Paises] ([Id],[Codigo],[Nombre]) VALUES (NEWID(), N'DO', N'República Dominicana');

